def _publish_out(slug: str) -> dict:
    from . import publish as PB
    d = PB.load(slug)
    f = PB.final_video(slug)
    t = PB.thumbnail_file(slug)
    d.pop("stored_status", None)
    return {**d, "slug": slug, "statuses": PB.STATUSES, "status_labels": PB.STATUS_LABELS,
            "video": f"out/{f.name}" if f else None, "video_path": str(f) if f else None,
            "folder": str(PROJECTS / slug / "out"), "thumbnail": t.name if t else None,
            "thumbnail_mtime": t.stat().st_mtime if t else None,
            "tags_chars": PB.tags_chars(d.get("tags") or []), "tag_limit": 500,
            "checklist": PB.checklist(slug, d), "claude": bool(claude_bin()),
            "job": next((j.public(tail=20) for j in reversed(JOBS.values())
                         if j.slug == slug and j.stage == "publish" and j.status == "running"), None)}


