    inside(PROJECTS, slug)
    try:
        PB.patch(slug, body)
    except ValueError as e:
        raise HTTPException(400, str(e)) from None
    return _publish_out(PB.parent_of(slug))


@app.post("/api/projects/{slug}/publish/generate")
def publish_generate(slug: str, llm: bool = True):
    from . import publish as PB
    inside(PROJECTS, slug)
    slug = PB.parent_of(slug)
    if any(j.slug == slug and j.stage == "publish" and j.status == "running" for j in JOBS.values()):
        raise HTTPException(409, "metadata is already being generated")
    cmd = [sys.executable, "-m", "mcstudio.publish", "generate", slug] + ([] if llm else ["--no-llm"])
    job = Job(slug, "publish", cmd, STUDIO)
    JOBS[job.id] = job
    return job.public()


@app.post("/api/projects/{slug}/publish/thumbnail")
async def publish_thumbnail(slug: str, file: UploadFile = File(...)):
    """Save the finished thumbnail (e.g. the ChatGPT image) as projects/<slug>/thumbnail.<ext>."""
    from . import publish as PB
    p = inside(PROJECTS, PB.parent_of(slug))
    ext = Path(file.filename or "").suffix.lower().lstrip(".")
    if ext not in ("png", "jpg", "jpeg", "webp"):
        raise HTTPException(400, "thumbnail must be png, jpg or webp")
    for old in p.glob("thumbnail.*"):
        old.unlink()
    with (p / f"thumbnail.{ext}").open("wb") as out:
        while chunk := await file.read(1 << 20):
            out.write(chunk)
    return _publish_out(p.name)


@app.post("/api/projects/{slug}/publish/open-folder")
def publish_open_folder(slug: str):
    from . import publish as PB
    p = inside(PROJECTS, PB.parent_of(slug))
    f = PB.final_video(p.name)
    if f:
        subprocess.Popen(["explorer", "/select,", str(f)])
    else:
        os.startfile(str(p / "out") if (p / "out").exists() else str(p))  # noqa: S606 - local desktop app
    return {"ok": True}


