let SET_SCHEMA = null;
const setSchema = async (fresh = false) => (SET_SCHEMA = fresh || !SET_SCHEMA ? await api("/api/settings/schema") : SET_SCHEMA);
const APPLIES = {
  plan: ["plan", "Used by the auto-editor when it plans an edit: re-plan (Auto-edit) to see the change."],
  render: ["render", "Applied by the renderer, also to existing edits: just re-render."],
  both: ["plan + render", "The auto-editor stops placing it AND the renderer strips it from existing edits."],
