    const spec = (p) => sch.sections.flatMap((s) => s.settings).find((s) => s.path === p);
    const cur = (p) => [...((o.project ? (shas(o.ov, p) ? sget(o.ov, p) : null) : val(p)) || [])];
    if (t.dataset.chip) {
