}
function applySettingsSearch(el) {
  const q = SET_UI.q.trim().toLowerCase();
  $$(".set-sec", el).forEach((sec) => {
    let n = 0;
    $$(".set-row", sec).forEach((r) => { const hit = !q || r.dataset.text.includes(q); r.hidden = !hit; n += hit; });
