// debounced autosave: collects changes, PATCHes once, toasts
function settingsSaver(url, after) {
  let pending = {}, timer = null;
  return (path, value) => {
    sput(pending, path, value);
    clearTimeout(timer);
    timer = setTimeout(async () => {
      const body = pending; pending = {};
      try { const r = await api(url, { method: "PATCH", body }); toast("✓ Settings saved"); after(r); }
      catch (e) { toast(e.message, true); after(null); }
    }, 350);
  };
}

