// ---------------------------------------------------------------- autopilot  [autopilot]
const AP_BADGE = { done: "r-clean", processing: "r-mild", queued: "r-mild", skipped: "", failed: "r-explicit" };
const fmtDur = (s) => s == null ? "" : s >= 3600 ? `${Math.floor(s / 3600)}h ${Math.round(s % 3600 / 60)}m` : s >= 60 ? `${Math.floor(s / 60)}m ${Math.round(s % 60)}s` : `${Math.round(s)}s`;
async function Autopilot() {
  let d;
  try { d = await api("/api/autopilot"); } catch (e) { view.innerHTML = `<div class="empty">${esc(e.message)}</div>`; return; }
  const c = d.config, st = d.status || {};
  const runRow = (e) => {
    const dur = e.finished && e.started ? fmtDur(e.finished - e.started) : e.status === "processing" ? "running…" : "";
    return `<div class="row" style="padding:8px 0;border-bottom:1px solid var(--line);gap:10px;align-items:flex-start;flex-wrap:wrap">
      <span class="badge ${AP_BADGE[e.status] ?? ""}">${esc(e.status)}</span>
      <div style="flex:1;min-width:220px"><b>${esc(e.name)}</b> <span class="faint">${esc(dur)}</span>
        ${e.title ? `<div class="muted" style="font-size:13px">${esc(e.title)}</div>` : ""}
        ${e.status === "processing" ? `<div class="muted" style="font-size:12px">${esc(e.stage || "")}${e.pct != null ? ` (${e.pct}%)` : ""}</div>` : ""}
        ${e.error ? `<div style="color:${e.status === "failed" ? "#ffb3b3" : "var(--muted)"};font-size:12px;white-space:pre-wrap">${esc(e.error)}</div>` : ""}
        ${(e.warnings || []).map((w) => `<div class="faint" style="font-size:12px">⚠ ${esc(w)}</div>`).join("")}</div>
      ${e.slug && e.status !== "queued" ? `<a class="btn small" href="#/project/${encodeURIComponent(e.slug)}">Open project</a>` : ""}
      ${e.out_dir ? `<button class="btn small" data-open="${esc(e.out_dir)}">Open folder</button>` : ""}
      ${e.status === "failed" || e.status === "skipped" ? `<button class="btn small" data-retry="${esc(e.key)}">Retry</button>` : ""}</div>`;
  };
  const dot = { off: "", idle: "ok", waiting: "", processing: "ok", stopped: "bad", locked: "bad" }[st.state] ?? "";
  view.innerHTML = `<div class="row"><div><h1>Autopilot</h1>
      <p class="sub">Play → stop OBS → close Minecraft → your finished video + Shorts + title/description/tags appear in <b>Finished/</b>. Nothing runs until you switch it on.</p></div></div>
    <div class="card row" style="gap:16px;align-items:center;flex-wrap:wrap">
      <label class="switch big" title="Autopilot on/off"><input type="checkbox" id="apOn" ${c.enabled ? "checked" : ""}><span></span></label>
      <div style="flex:1;min-width:260px"><div style="font-size:20px;font-weight:700">${c.enabled ? "Autopilot is ON" : "Autopilot is OFF"}</div>
        <div class="row" style="gap:8px"><span class="dot ${dot}"></span><span id="apMsg">${esc(st.message || "")}</span></div></div>
      <button class="btn primary" id="apNow" title="Edit the pending recordings right now, even if Autopilot is off or Minecraft is open">Process now</button>
      <button class="btn" id="apScan">Rescan</button>
      <button class="btn" data-open="">Open Finished folder</button></div>
    <div class="card" style="margin-top:12px"><b>Options</b>
      <div class="set-list" id="apSet" style="margin-top:8px"></div></div>
    <div class="card" style="margin-top:12px"><b>Recent runs</b> <span class="faint">${Object.entries(d.counts || {}).map(([k, v]) => `${v} ${k}`).join(" · ")}</span>
      ${d.runs.length ? d.runs.map(runRow).join("") : `<div class="empty" style="padding:16px">No recordings seen yet. Record something with OBS.</div>`}</div>
    <details class="card" style="margin-top:12px"><summary><b>Start Autopilot when Windows starts</b> (optional)</summary>
      <p class="muted">Autopilot runs inside this studio window. To have it work even when the studio is closed, make a Startup shortcut:</p>
      <ol class="muted"><li>Press <code>Win+R</code>, type <code>shell:startup</code>, Enter.</li>
        <li>Right-click, New, Shortcut. Target:<br><code>cmd /c "cd /d C:\\Users\\edmem\\OneDrive\\Desktop\\Minecraft Channel\\studio &amp;&amp; uv run mcs autopilot run"</code></li>
        <li>Name it "MC Autopilot" (set "Run: Minimized").</li></ol>
      <p class="faint">Only one copy ever works at a time (lock file), so the studio and the shortcut can both be open. The originals in your OBS folders are never touched; nothing is uploaded.</p></details>`;
  // options: the generic settings renderer, autopilot section only (the big switch above is the master switch)
  const sch = await setSchema();
  const sec = sch.sections.find((x) => x.key === "autopilot");
  const cur = await api("/api/settings");
  const one = { sections: [{ ...sec, master: null, settings: sec.settings.filter((x) => x.key !== "enabled") }] };
  const save = settingsSaver("/api/settings", () => Autopilot());
  renderSettings($("#apSet"), one, { project: false, eff: cur.settings, defs: cur.defaults, onSet: (p, v) => save(p, v), onReset: () => {} });
  const sh = $("#apSet .set-sec");
  if (sh) { sh.classList.add("open"); $(".set-head", sh).style.display = "none"; }
  $("#apOn").onchange = async (e) => {
    try { await api("/api/autopilot/enable", { method: "POST", body: { enabled: e.target.checked } }); toast(e.target.checked ? "Autopilot is ON" : "Autopilot is OFF"); Autopilot(); }
    catch (er) { toast(er.message, true); }
  };
  $("#apNow").onclick = async () => { try { await api("/api/autopilot/process-now", { method: "POST", body: {} }); toast("Checking for recordings now…"); setTimeout(Autopilot, 3000); } catch (e) { toast(e.message, true); } };
  $("#apScan").onclick = async () => { try { await api("/api/autopilot/rescan", { method: "POST", body: {} }); toast("Rescanned"); Autopilot(); } catch (e) { toast(e.message, true); } };
  view.onclick = async (e) => {
    const o = e.target.closest("[data-open]"), r = e.target.closest("[data-retry]");
    try {
      if (o) await api("/api/autopilot/open-folder", { method: "POST", body: { path: o.dataset.open } });
      if (r) { await api("/api/autopilot/retry", { method: "POST", body: { key: r.dataset.retry } }); toast("Queued again"); Autopilot(); }
    } catch (er) { toast(er.message, true); }
  };
  pollers.push(setInterval(() => { if (location.hash === "#/autopilot" && !document.activeElement?.closest("#apSet")) Autopilot(); }, 4000));
}

